41: static inline void khrIcdOsDirEntryValidateAndAdd(const char *d_name, const char *path,
42:                                                   const char *extension, khrIcdFileAdd addFunc)
43: {
44:     struct stat statBuff;
45:     char* fileName = NULL;
46: 
47:     // make sure the file name ends in `extension` (eg. .icd, or .lay)
48:     if (strlen(extension) > strlen(d_name))
49:     {
50:         return;
51:     }
52:     if (strcmp(d_name + strlen(d_name) - strlen(extension), extension))
53:     {
54:         return;
55:     }
56: 
57:     // allocate space for the full path of the vendor library name
58:     fileName = malloc(strlen(d_name) + strlen(path) + 2);
59:     if (!fileName)
60:     {
61:         KHR_ICD_TRACE("Failed allocate space for ICD file path\n");
62:         return;
63:     }
64:     sprintf(fileName, "%s/%s", path, d_name);
65: 
66:     if (stat(fileName, &statBuff))
67:     {
68:         KHR_ICD_TRACE("Failed stat for: %s, continuing\n", fileName);
69:         free(fileName);
70:         return;
71:     }
72: 
73:     if (S_ISREG(statBuff.st_mode) || S_ISLNK(statBuff.st_mode))
74:     {
75:         FILE *fin = NULL;
76:         char* buffer = NULL;
77:         long bufferSize = 0;
78: 
79:         // open the file and read its contents
80:         fin = fopen(fileName, "r");
81:         if (!fin)
82:         {
83:             free(fileName);
84:             return;
85:         }
86:         fseek(fin, 0, SEEK_END);
87:         bufferSize = ftell(fin);
88: 
89:         buffer = malloc(bufferSize+1);
90:         if (!buffer)
91:         {
92:             free(fileName);
93:             fclose(fin);
94:             return;
95:         }
96:         memset(buffer, 0, bufferSize+1);
97:         fseek(fin, 0, SEEK_SET);
98:         if (bufferSize != (long)fread(buffer, 1, bufferSize, fin))
99:         {
100:             free(fileName);
101:             free(buffer);
102:             fclose(fin);
103:             return;
104:         }
105:         // ignore a newline at the end of the file
106:         if (buffer[bufferSize-1] == '\n') buffer[bufferSize-1] = '\0';
107: 
108:         // load the string read from the file
109:         addFunc(buffer);
110: 
111:         free(fileName);
112:         free(buffer);
113:         fclose(fin);
114:      }
115:      else
116:      {
117:          KHR_ICD_TRACE("File %s is not a regular file nor symbolic link, continuing\n", fileName);
118:          free(fileName);
119:      }
120: }
