128: static int compareDirElem(const void *a, const void *b)
129: {
130:     // sort files the same way libc alpahnumerically sorts directory entries.
131:     return strcoll(((const struct dirElem *)a)->d_name, ((const struct dirElem *)b)->d_name);
132: }
