50:     BOOL result = TRUE;
51:     if (pWinAdapterEnd == pWinAdapterCapacity)
52:     {
53:         size_t oldCapacity = pWinAdapterCapacity - pWinAdapterBegin;
54:         size_t newCapacity = oldCapacity;
55:         if (0 == newCapacity)
56:         {
57:             newCapacity = 1;
