24: char *khrIcd_getenv(const char *name) {
25:     char *retVal;
26:     DWORD valSize;
27: 
28:     valSize = GetEnvironmentVariableA(name, NULL, 0);
29: 
30:     // valSize DOES include the null terminator, so for any set variable
31:     // will always be at least 1. If it's 0, the variable wasn't set.
32:     if (valSize == 0) return NULL;
33: 
34:     // Allocate the space necessary for the registry entry
35:     retVal = (char *)malloc(valSize);
36: 
37:     if (NULL != retVal) {
38:         GetEnvironmentVariableA(name, retVal, valSize);
39:     }
40: 
41:     return retVal;
42: }
