287: static inline void* clGetExtensionFunctionAddressForPlatform_body(
288:     cl_platform_id platform,
289:     const char* function_name)
290: {
291:     void* function_address = NULL;
292: 
293:     KHR_ICD_VALIDATE_HANDLE_RETURN_ERROR(function_name, NULL);
294: 
295:     // check if this is an ICD-aware extension
296:     function_address = khrIcdGetExtensionFunctionAddress(function_name);
297:     if (function_address)
298:     {
299:         return function_address;
300:     }
301: 
302:     // This is not an ICD-aware extension, so call into the implementation
303:     // to get the extension function address.
304: 
305:     KHR_ICD_VALIDATE_HANDLE_RETURN_ERROR(platform, NULL);
306: 
307: #define KHR_ICD_REJECT_EXTENSION_FUNCTION(name)                                \
308:     do                                                                         \
309:     {                                                                          \
310:         if (!strcmp(function_name, #name))                                     \
311:         {                                                                      \
312:             return NULL;                                                       \
313:         }                                                                      \
314:     } while (0)
315: 
316:     // Reject ICD-specific functions that could be misused by users
317:     KHR_ICD_REJECT_EXTENSION_FUNCTION(clIcdGetPlatformIDsKHR);
318:     KHR_ICD_REJECT_EXTENSION_FUNCTION(clIcdGetFunctionAddressForPlatformKHR);
319:     KHR_ICD_REJECT_EXTENSION_FUNCTION(clIcdSetPlatformDispatchDataKHR);
320: 
321:     return KHR_ICD2_DISPATCH(platform)->clGetExtensionFunctionAddressForPlatform(
322:         platform,
323:         function_name);
324: #undef KHR_ICD_REJECT_EXTENSION_FUNCTION
325: }
